application.css:
* {
  box-sizing: border-box;
}

:root {
  color: #172033;
  background: #eef2f7;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}

body {
  margin: 0;
  min-width: 0;
}

.app-shell {
  width: min(100% - 2rem, 44rem);
  margin: 0 auto;
  padding: 3rem 0 4rem;
}

.app-header {
  margin-bottom: 2rem;
}

.eyebrow {
  margin: 0 0 .35rem;
  color: #315ca8;
  font-size: .78rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
}

h1, h2, p {
  margin-top: 0;
}

h1 {
  margin-bottom: .5rem;
  font-size: clamp(2rem, 7vw, 3rem);
  line-height: 1.1;
}

h2 {
  margin-bottom: 1rem;
  font-size: 1.2rem;
}

.intro {
  max-width: 34rem;
  margin-bottom: 0;
  color: #4b5870;
}

.todo-panel, .tasks-section {
  padding: 1.4rem;
  border: 1px solid #d6deea;
  border-radius: .75rem;
  background: #fff;
  box-shadow: 0 .25rem 1rem rgb(26 42 67 / 7%);
}

.tasks-section {
  margin-top: 1.25rem;
}

.entry-row {
  display: flex;
  align-items: end;
  gap: .75rem;
}

.field-group {
  flex: 1 1 auto;
  min-width: 0;
}

label {
  display: block;
  margin-bottom: .4rem;
  font-size: .9rem;
  font-weight: 650;
}

input[type="text"] {
  width: 100%;
  min-height: 2.75rem;
  padding: .65rem .75rem;
  border: 1px solid #8997ad;
  border-radius: .4rem;
  color: #172033;
  background: #fff;
  font: inherit;
}

button {
  min-height: 2.75rem;
  padding: .6rem .95rem;
  border: 0;
  border-radius: .4rem;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

.primary-button {
  color: #fff;
  background: #2457a6;
}

.primary-button:hover, .primary-button:focus-visible {
  background: #174484;
}

.form-message {
  min-height: 1.5em;
  margin: .55rem 0 0;
  color: #a32626;
  font-size: .9rem;
}

.tasks-heading-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.tasks-heading-row h2, .count {
  margin-bottom: 0;
}

.count {
  color: #4b5870;
  font-size: .9rem;
}

.task-list {
  display: grid;
  gap: .65rem;
  margin: 1.1rem 0 0;
  padding: 0;
  list-style: none;
}

.task-item {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .75rem;
  border: 1px solid #d6deea;
  border-radius: .45rem;
  background: #f8fafc;
}

.task-toggle {
  width: 1.15rem;
  height: 1.15rem;
  flex: 0 0 auto;
  accent-color: #2457a6;
}

.task-text {
  min-width: 0;
  flex: 1;
  overflow-wrap: anywhere;
}

.task-item[data-completed="true"] .task-text {
  color: #596579;
  text-decoration: line-through;
}

.delete-button {
  min-height: 2.25rem;
  padding: .4rem .65rem;
  color: #9a2525;
  background: transparent;
}

.delete-button:hover, .delete-button:focus-visible {
  background: #fceaea;
}

.empty-state {
  margin: 1.1rem 0 0;
  color: #596579;
  text-align: center;
}

:focus-visible {
  outline: 3px solid #f0a600;
  outline-offset: 2px;
}

@media (max-width:  thirtyrem) {
  .entry-row {
    align-items: stretch;
    flex-direction: column;
  }

  .primary-button {
    width: 100%;
  }
}

@media (max-width: 480px) {
  .app-shell {
    width: min(100% - 1rem, 44rem);
    padding-top: 2rem;
  }

  .todo-panel, .tasks-section {
    padding: 1rem;
  }
}

